#!/usr/bin/env python3
"""Construit les quatre brouillons B226 depuis les textes propres à chaque scénario."""
from pathlib import Path
import json, html, hashlib
from lxml import html as lh
from construire import p,refs,table,window,mono,page,DX,ROOT
from contenu_a import legal_toolkit
from b_scenarios import SCENARIOS

PARTS={1:[1,2],2:[3,4,5],3:[6,7],4:[8,9,10]}
def para(*x):return ''.join(p(t) for t in x)
def rowwindows(title,rows,rs,kind='fenetre'):
 # Les faits sont déjà dans le tableau du point: aucune copie répétée n'est ajoutée.
 # Les pièges du point14 n'ont pas de tableau antérieur et gardent leur fenêtre propre.
 if kind!='cas':return ''
 return ''.join(window(f'{title} {j}. '+row[0],para(*row[1:])+refs(*rs),kind) for j,row in enumerate(rows,1))

def decision_tools(d,n):
 r=d['refs']; case=d['case']; title=DX[n-1][0]
 return window('Le candidat construit une décision partageable sans confondre les niveaux de preuve.',
  para('Le diagnostic médical, le constat fonctionnel et la décision sociale répondent à des questions différentes. Pour ce scénario, le médecin dit ce qu’il a observé, ce que la personne rapporte et ce qui reste à vérifier. Cette distinction évite de transformer une hypothèse en fait établi.',
   'Le médecin applique cette distinction au cas présenté au point1; les hypothèses peuvent coexister.',
   'Le candidat formule d’abord la question qui change immédiatement la conduite: existe-t-il un danger ou un besoin essentiel non couvert? Il examine ensuite quel obstacle peut être corrigé dans les conditions réelles de la personne. Une solution proposée n’est considérée comme obtenue qu’après vérification du relais.',
   'Le compte rendu indique la source de l’information, les adaptations de communication, le souhait exprimé et les limites du raisonnement. Si une décision relève d’une autorité, d’un assureur ou d’un spécialiste, le médecin précise sa contribution sans prétendre décider à leur place.')+
  table(['Le niveau est nommé.','La formulation reste vérifiable.','Le piège est évité.'],[
   ['Le constat clinique est décrit.','Le médecin consigne les symptômes et les observations effectivement recueillis.','Il n’attribue pas automatiquement une cause unique au contexte psychosocial ou environnemental.'],
   ['Le souhait de la personne est recueilli.','Le médecin précise la décision discutée et les informations comprises.','Il ne transforme pas un désaccord en incapacité de discernement.'],
   ['Le relais est vérifié.','Le plan nomme une tâche, un responsable et une condition de réévaluation.','Il ne confond pas une demande envoyée avec une aide déjà disponible.'],
   ['L’incertitude est conservée.','Le compte rendu nomme l’information manquante et la démarche pour l’obtenir.','Il ne comble pas une lacune par un seuil ou une dose de mémoire.']])+refs(*r))

def special(d,n):
 t=DX[n-1][0]
 return window('Les situations particulières modifient le cadre et les moyens sans imposer des seuils artificiels.',
  p('Le scénario «'+t+'» reste transposé à un problème de parcours, de participation ou d’exposition. Les adaptations ci-dessous décrivent les vérifications nécessaires; elles ne remplacent pas les recommandations de chaque maladie associée.')+
  table(['La situation est reconnue.','Le clinicien adapte la démarche.','La limite reste explicite.'],[
   ['La personne est enceinte ou allaite.','Le médecin vérifie les besoins propres, les traitements et les contraintes de la grossesse avec l’équipe concernée.','Les risques et prescriptions d’un produit ne sont pas déduits d’une recommandation psychosociale générale.'],
   ['La personne est âgée ou dépendante.','L’équipe vérifie les capacités fonctionnelles, les moyens sensoriels et la disponibilité réelle des aides.','La dépendance et l’âge ne prouvent pas à eux seuls une incapacité de discernement.'],
   ['La consultation concerne un enfant ou un adolescent.','Le médecin adapte l’information et apprécie le discernement pour la décision, en clarifiant la place des représentants et du jeune.','Les droits personnels et le secret ne se résument pas à une règle automatique fondée sur la seule minorité.'],
   ['La personne a une insuffisance rénale ou hépatique.','Le médecin reprend les diagnostics, les prescriptions et les informations professionnelles avant une adaptation de médicament ou de boisson.','Aucun palier de débit de filtration glomérulaire ni dose hépatique non vérifiés n’est inventé.'],
   ['La personne présente un handicap de communication.','Le professionnel utilise une langue, un support ou un interprète adaptés, puis vérifie la compréhension et l’application.','Une difficulté persistante est analysée dans ses conditions réelles avant toute conclusion sur les capacités.'],
   ['La personne est incapable de discernement pour la décision concernée.','Le médecin recherche les directives et la représentation applicable; en urgence il considère la volonté présumée et les intérêts de la personne.','L’ordre légal et les conditions ne sont pas remplacés par la présence du proche le plus disponible.']])+p('Le candidat choisit uniquement les adaptations réellement pertinentes pour ce cas, puis indique les informations à obtenir. Il n’applique pas mécaniquement toutes les lignes à la même personne.')+refs('S17','S24','S07','S23'))

def discharge(d,n):
 return window('La fin du contact exige un relais utilisable et des critères explicités.',
  para('Ce scénario transversal ne possède pas des seuils universels de sortie d’hospitalisation. Une personne hospitalisée doit d’abord satisfaire les critères de la maladie ou de la complication traitée; ces critères ne sont pas remplacés par une grille sociale.',
   'Le passage au suivi ambulatoire exige que les besoins cliniques encore présents soient compatibles avec le lieu prévu. Le patient ou la personne autorisée doit comprendre les éléments de sécurité et savoir comment demander une réévaluation. Les moyens nécessaires doivent être disponibles plutôt que simplement recommandés.')+
  table(['Le domaine est vérifié.','Le critère est formulé comme un fait.','Une réponse négative change la conduite.'],[
   ['La stabilité clinique est appréciée.','L’équipe compétente juge que l’état et la surveillance requise sont compatibles avec le cadre proposé.','Le niveau de soins est reconsidéré si le besoin dépasse les moyens disponibles.'],
   ['Le plan est compris.','La personne reformule les actions essentielles et les signes qui demandent un recours.','Le médecin reprend l’explication et adapte la communication avant de conclure.'],
   ['Les ressources sont présentes.','Les aides, dispositifs, traitements ou conditions environnementales nécessaires sont confirmés.','Une aide absente est traitée comme une lacune réelle du plan.'],
   ['Le relais est identifié.','Le prochain interlocuteur et la responsabilité pendant l’intervalle sont clarifiés.','Un courrier sans acceptation ne suffit pas à clore la coordination.'],
   ['Le cadre de décision est respecté.','Le consentement, les souhaits et la représentation éventuelle sont documentés.','Un désaccord ou un doute décisionnel est examiné avant une substitution injustifiée.']])+
  p('La vignette est fictive. '+d['case'])+p('Le candidat applique ces domaines au risque propre du cas et indique celui qui reste non satisfait. Il n’annonce pas un retour sûr si la personne ne peut pas utiliser le plan dans son lieu de vie.')+refs(*d['refs']))

def prescriptions(d,n):
 return window('La limite médicamenteuse est séparée de la conduite de coordination.',
  para('Le contexte psychosocial ou environnemental ne constitue pas à lui seul une indication à ajouter un médicament. Le médecin vérifie d’abord la maladie effectivement traitée, les prises réelles, les effets rapportés et les autres prescripteurs.',
   'Lorsqu’un médicament est envisagé, la dénomination commune internationale, la spécialité suisse autorisée, le numéro d’autorisation, la dose, la voie, le rythme, la durée, les adaptations rénale et hépatique et les interactions doivent être lus dans l’information professionnelle AIPS applicable. Le présent fichier ne prétend pas avoir vérifié une fiche de produit en ouvrant le portail.',
   'Les éléments non vérifiés portent la mention «À vérifier (AIPS)». Cette mention ne constitue pas une prescription utilisable: elle indique une lacune à résoudre avant l’acte. Les changements d’un traitement existant doivent avoir un responsable et une consigne de suivi.')+
  table(['Le champ est contrôlé.','Le résultat de ce brouillon est explicite.','La conséquence pratique est indiquée.'],[
   ['La dose et la spécialité sont recherchées.','Aucune dose ni spécialité de produit n’est présentée comme vérifiée dans cette partie.','Le prescripteur consulte la monographie exacte avant toute prescription.'],
   ['Les adaptations et interactions sont examinées.','Les paramètres propres au produit restent à vérifier AIPS.','Une maladie rénale, hépatique ou une polymédication empêche toute extrapolation automatique.'],
   ['Le traitement déjà pris est documenté.','La liste théorique est confrontée à ce que la personne utilise réellement.','Une divergence est clarifiée avant une modification ou une transmission.'],
   ['La décision est suivie.','Le responsable, le motif et la réévaluation sont explicités.','Une modification temporaire n’est pas poursuivie sans contrôle de sa pertinence.']])+refs('S23',*d['refs']))

def source_reading(d,n):
 return window('La lecture critique empêche une généralisation abusive.',
  para('Le scénario «'+DX[n-1][0]+'» utilise les sources indiquées à chaque fenêtre. Les chiffres de population conservent leur année et leur dénominateur; les exemples pédagogiques restent fictifs. Le médecin ne transforme pas une association de groupe en prédiction individuelle.',
   d['epi'],
   'Le candidat distingue une recommandation professionnelle, une page d’information et une disposition légale. Une page locale peut montrer une organisation possible sans imposer cette organisation à tout le pays. Le fait qu’un document soit hébergé en2026 ne prouve pas que son contenu médical a été révisé cette année.',
   'Une absence de donnée n’est pas une valeur nulle. Si les passages consultés ne permettent pas une fréquence, une performance de test ou un seuil, le cours le dit et décrit la question à vérifier. La décision clinique conserve alors ses limites et le niveau de prudence nécessaire.')+refs(*d['refs']))

def build_mono(n):
 d=SCENARIOS[n];rs=d['refs'];w=lambda title,txt:window(title,p(txt)+refs(*rs))
 s=[]
 s.append((d['focus'],window('La situation clinique fictive précise ce que le scénario doit résoudre.',p(d['case'])+p('Le premier objectif du candidat est de préciser le danger éventuel et le besoin que la personne considère prioritaire. Le second est d’organiser une réponse dont la disponibilité et l’application peuvent être vérifiées. Cette vignette ne fournit ni un seuil supplémentaire ni une estimation de risque individuelle.')+refs(*rs))+decision_tools(d,n)))
 s.append((d['epi'],source_reading(d,n)))
 s.append(('Le raisonnement relie les contraintes, leurs effets sur le fonctionnement et les moyens qui peuvent les corriger. Les mécanismes proposés restent distincts d’une causalité individuelle démontrée.',table(['La perturbation est décrite.','L’exploration met le problème en évidence.','La stratégie corrige le mécanisme visé.'],d['mechanism'])+rowwindows('Le lien est expliqué au cas',[(a,b,c,'La vignette est fictive. '+d['case'],'Le candidat vérifie que cette chaîne est réellement présente avant de choisir la correction. Une association plausible ne prouve pas qu’elle explique tous les symptômes.') for a,b,c in d['mechanism']],rs)))
 s.append(('La démarche traite les hypothèses dangereuses avant les obstacles fréquents et conserve les causes associées. Chaque ligne relie un constat discriminant, une décision et son piège.',table(['L’hypothèse est nommée.','L’élément discriminant est recherché.','La décision suit le résultat.','Le piège est explicite.'],d['diff'])+rowwindows('La distinction est appliquée dans la branche',[(a,b,c,e,'La vignette est fictive. '+d['case']) for a,b,c,e in d['diff']],rs)))
 s.append(('L’anamnèse précise la chronologie, les besoins et les ressources sans attribuer d’emblée la situation à une seule cause. Une question de sécurité modifie la priorité si elle révèle un danger actuel.',table(['Le médecin pose une question précise.','La raison est expliquée.','La réponse modifie la conduite.'],d['ask'])+rowwindows('La question est reprise dans l’entretien',[(a,b,c,'Le médecin s’adresse d’abord à la personne et vérifie les conditions de communication. Il distingue le propos rapporté et les faits confirmés, puis demande une reformulation des éléments importants.') for a,b,c in d['ask']],rs)))
 s.append(('L’examen commence par la référence habituelle et les capacités présentes, puis recherche ce qui est nouveau ou insuffisant. L’absence de signe propre à un problème social n’interdit pas l’examen de ses conséquences cliniques.',table(['La référence normale est décrite.','La méthode utile est précisée.','Le résultat anormal change la conduite.'],d['exam'])+rowwindows('L’observation est interprétée dans la situation',[(a,b,c,'La vignette est fictive. '+d['case'],'La portée du signe dépend de la méthode, du contexte et de l’évolution. Aucun rendement diagnostique non trouvé dans les sources consultées n’est inventé.') for a,b,c in d['exam']],rs)))
 s.append(('Les profils suivants regroupent des signes utiles sans constituer des maladies supplémentaires. Les signes fonctionnels, les observations et leur mécanisme restent séparés.',table(['Le profil est défini.','Les signes fonctionnels sont recherchés.','Les constatations sont interprétées.','Le mécanisme relie les données.'],d['syndromes'])+rowwindows('Le profil est développé dans la fenêtre',[(a,b,c,e,'La vignette est fictive. '+d['case'],'Le profil ne devient pas une preuve isolée: le médecin vérifie la cohérence et les autres hypothèses avant de décider.') for a,b,c,e in d['syndromes']],rs)))
 s.append((d['criteria'],window('Le positif, le négatif et l’incertain ne sont pas interchangeables.',table(['Le résultat est qualifié.','La signification est précisée.','Le médecin décide de la suite.'],[
 ['Les éléments concordent avec la situation décrite.','Le médecin dispose des constats nécessaires dans le périmètre effectivement évalué.','Il engage une réponse proportionnée et garde les diagnostics associés ouverts.'],
 ['Un élément recherché n’est pas retrouvé.','Cette absence vaut pour la méthode et le moment considérés.','Il ne transforme pas cette seule absence en exclusion de tout risque.'],
 ['L’information est incomplète ou discordante.','Les données ne permettent pas une conclusion suffisamment solide.','Il indique ce qui manque et choisit une démarche de clarification sans retarder un soin urgent.']])+p('Le médecin conclut en séparant ce qui est établi, ce qui reste incertain et ce qui change immédiatement la conduite.')+refs(*rs))))
 s.append(('9.a La référence dépend de la question clinique ou situationnelle. 9.b La première intention privilégie les informations qui changent la décision; 9.c les adaptations répondent aux contraintes réelles; 9.d la seconde intention clarifie une hypothèse persistante. Aucun panel automatique n’est proposé pour tout patient chronique.',table(['L’exploration répond à une question.','Le protocole est défini.','Le résultat est interprété.','La conduite découle de la limite.'],d['tests'])+rowwindows('L’exploration est détaillée dans la rubrique',[(a,b,c,e,'La vignette est fictive. '+d['case'],'Avant de demander cet outil, le médecin précise quelle décision dépendra du résultat. Si la méthode, le seuil ou la performance n’ont pas été lus, il n’en fabrique pas une version simplifiée.') for a,b,c,e in d['tests']],rs)+special(d,n)))
 algo=[['Le premier constat révèle un danger actuel.','Le médecin suit la conduite urgente et sécurise le relais.','Il réévalue le besoin de soins avant les objectifs différés.']]
 algo += [[a,b,c] for a,b,c in d['care']]
 s.append(('Chaque embranchement relie un constat et une décision. Les branches peuvent se cumuler; l’ordre pédagogique ne fixe jamais la priorité clinique.',table(['Le constat guide la branche.','La décision est engagée.','Le contrôle vérifie le résultat.'],algo)+decision_tools(d,n)))
 urgency=window('L’urgence suit une chronologie clinique et un relais continu.', ''.join(p(f'À l’étape{j}, '+x[0].lower()+x[1:]) for j,x in enumerate(d['urgent'],1))+p('Ces étapes suivent l’état clinique et ne sont pas des délais minute par minute validés. Aucun chiffre de protocole non consulté n’est ajouté. La gravité peut imposer de solliciter immédiatement l’équipe d’urgence plutôt que d’achever l’ordre de lecture.')+refs(*rs))
 care=window('11.A Le but et ses critères restent individualisés.',p('Le résultat attendu est formulé avec la personne dans un domaine pertinent: sécurité, accès, fonctionnement, charge ou exposition. Un objectif pédagogique peut préciser une action et son responsable; il n’est pas une recommandation de délai universel.')+table(['Le but est défini.','Le moyen suit le mécanisme.','Le résultat est contrôlé.'],d['care'])+refs(*rs))
 surveillance=window('11.C La surveillance distingue réalisation, effet et tolérance.',table(['Le domaine est suivi.','Le contrôle répond au but.','Le résultat défavorable change le plan.'],d['follow'])+p('Le moment de la réévaluation dépend du risque, de la maladie et de la mesure mise en place. Si un délai ou un seuil de toxicité propre à un traitement n’a pas été vérifié, il reste à vérifier dans sa recommandation et son information professionnelle; il n’est pas remplacé par une date arbitraire.')+refs(*rs))
 prognosis=window('11.D Le pronostic porte sur la situation et les maladies associées.',p('La résolution d’un obstacle améliore une condition de soin sans prouver la guérison de la maladie chronique. Le suivi vérifie le maintien du résultat, l’apparition de nouveaux besoins et la capacité à utiliser le relais. La rechute du problème peut refléter une modification de ressources ou d’exposition plutôt qu’un échec personnel.')+p('Aucun taux de guérison ni résultat de recherche2026 non trouvé dans les sources consultées n’est inventé. Les dates des documents et les questions restant ouvertes figurent dans les sources et le questionnaire de limites.')+refs(*rs))
 s.append(('11.A Le but est une sécurité et une participation vérifiables. 11.B Les moyens répondent au mécanisme et aux ressources; 11.C la surveillance vérifie les résultats et les difficultés; 11.D le pronostic distingue résolution du problème situationnel et évolution de la maladie.',urgency+care+window('11.B Les moyens sont choisis dans un ordre raisonné.',table(['Le besoin est priorisé.','La réponse est proposée.','La limite est reconnue.'],d['care'])+refs(*rs))+prescriptions(d,n)+surveillance+prognosis+discharge(d,n)))
 s.append(('La prévention primaire réduit l’apparition du problème évitable; la prévention secondaire repère plus tôt sa présence; la prévention tertiaire limite le retentissement et la récidive. Chaque niveau reste compatible avec les préférences et le contexte de la personne.',table(['Le niveau est appliqué.','L’action répond au scénario.','La vérification reste concrète.'],[
 ['La prévention primaire anticipe une vulnérabilité.','Le professionnel discute des ressources et du plan avant une rupture ou une exposition évitable.','La personne sait quelle première action utiliser dans son contexte.'],
 ['La prévention secondaire recherche un changement précoce.','Le professionnel pose les questions propres au scénario et compare la situation actuelle et antérieure.','Une réponse préoccupante conduit à une évaluation, pas seulement à une case cochée.'],
 ['La prévention tertiaire sécurise la continuité après un épisode.','Le relais maintient les aides et les soins utiles et réévalue les difficultés.','L’équipe vérifie que la solution reste disponible dans la durée.']])+rowwindows('La prévention s’appuie sur le levier',[(a,b,c,'La vignette est fictive. '+d['case']) for a,b,c in d['mechanism']],rs)))
 keys=['Le médecin recherche d’abord le danger et ne l’explique pas automatiquement par le contexte.','Il distingue les faits cliniques, le vécu, les ressources et les décisions d’autres organismes.','Il vérifie ce que la personne comprend et peut réellement utiliser.','Il confirme le relais et conserve les limites de preuve avant de conclure.']
 s.append((' '.join(keys),window('Le raisonnement est récapitulé à partir du cas.',''.join(p(a+' '+b+' '+c) for a,b,c in d['care'])+refs(*rs))))
 s.append(('Les questions suivantes testent des confusions qui changent la conduite. Les vignettes sont pédagogiques et ne prétendent pas reproduire un sujet officiel de l’examen fédéral.',rowwindows('La question d’examen se pose dans le cas',[(a,'La réponse correcte est la suivante: '+b,'Le piège est explicite: '+c,'Le candidat justifie sa réponse par le type de donnée et le cadre applicable. Il dit aussi quelle information manque avant une décision plus précise; une réponse exacte conserve cette limite.') for a,b,c in d['pitfalls']],rs,'cas')))
 assert len(s)==14
 return mono(f'DX.{n} · {DX[n-1][0]} — Le scénario est développé en quatorze points.',s,f'dx{n}',True)

def legal_appendix(part):
 groups={1:['S24','S26','S27','S28'],2:['S24','S25','S27','S28'],3:['S24','S26','S28'],4:['S24','S26','S28','S29']}[part]
 tree=lh.fragment_fromstring(legal_toolkit(),create_parent='div')
 out='<section><h3><strong>Les règles utiles restent consultables dans ce fichier autonome.</strong></h3>'+p('Le médecin utilise uniquement les articles correspondant à la décision du cas. Les extraits exacts et leurs états sont reproduits pour contrôler les conditions et exceptions; leur présence ne signifie pas que chaque article s’applique à chaque patient.')
 for e in tree.xpath('./section/details'):
  hs=e.xpath('.//a[starts-with(@href,"#source-")]/@href')
  if any('#source-'+x in hs for x in groups):out+=lh.tostring(e,encoding='unicode')
 return out+'</section>'

def shared_tools(indices):
 rows=[]
 for n in indices:
  d=SCENARIOS[n];rows.append([f'Le scénario DX.{n} concerne {DX[n-1][0].lower()}.',d['ask'][0][0],d['care'][0][1],d['follow'][0][2]])
 return '<section><h3><strong>Le relais transforme le raisonnement en plan utilisable.</strong></h3>'+p('Cette grille de travail est une construction pédagogique appliquée aux sources. Elle ne constitue ni une échelle validée ni une règle universelle de délai. Les informations de santé sont partagées seulement dans le cadre autorisé et à la mesure du besoin.')+table(['Le scénario est nommé.','Le besoin est reformulé.','La première réponse est engagée.','Le résultat impose une réévaluation si nécessaire.'],rows)+window('La communication vérifie une compréhension utile à l’action.',
 para('Le professionnel explique d’abord la décision et les raisons qui comptent pour la personne. Il utilise une langue et un support adaptés, laisse une place aux questions et distingue les choix possibles. Il demande ensuite à la personne de montrer comment elle utilisera le plan.',
 'Une reformulation insuffisante conduit à améliorer l’explication. Si un obstacle linguistique persiste, l’interprétariat professionnel est organisé selon les ressources et modalités vérifiées; le financement n’est pas promis sans contrôle. La traduction ne retire pas au médecin la responsabilité de l’évaluation et du consentement.',
 'Le compte rendu précise les adaptations utiles pour l’équipe suivante. Il évite les jugements sur la motivation ou les capacités à partir d’un échange mal adapté. La personne peut comprendre un choix et le refuser; le médecin examine alors ses raisons et le cadre décisionnel plutôt que de conclure automatiquement à l’incapacité.')+
 table(['Le professionnel vérifie une étape.','Le résultat attendu est observable.','Le résultat insuffisant appelle une correction.'],[
 ['Le problème prioritaire est décrit par la personne.','Elle explique ce qui compte et ce qu’elle souhaite obtenir ou éviter.','Le professionnel clarifie le besoin avant de multiplier les conseils.'],
 ['Le plan est expliqué dans une forme accessible.','La personne identifie l’action essentielle et le recours en cas de difficulté.','L’explication et son support sont adaptés.'],
 ['La réalisation est démontrée ou décrite.','La personne montre les étapes qui lui incombent.','L’équipe traite l’obstacle pratique et vérifie de nouveau.'],
 ['Le partage d’informations est explicite.','Le professionnel sait qui peut recevoir quoi pour quel objet.','Il clarifie le consentement ou la base légale avant un échange non urgent.']])+refs('S02','S03','S07','S17','S28'))+window('La conciliation des traitements précède toute modification.',
 para('Le médecin confronte ordonnance, prises réelles et compréhension. Il demande aussi les interruptions, les produits non prescrits et les décisions d’autres intervenants. Une divergence n’est pas interprétée d’emblée comme un refus volontaire.',
 'La liste transmise identifie les informations confirmées et celles qui restent à vérifier. Une dose n’est présentée comme validée que si la fiche professionnelle exacte a été consultée. La surveillance propre à la maladie ou au médicament reste sous la responsabilité du prescripteur compétent.',
 'La vignette est fictive. Une personne suit une consigne temporaire reçue lors d’un épisode aigu mais continue ensuite sans réévaluation. Le médecin clarifie le motif initial, l’évolution et le responsable avant d’annoncer une nouvelle conduite. L’existence d’une ancienne ordonnance ne prouve pas la pertinence de sa poursuite dans un contexte modifié.')+refs('S02','S23'))+window('Le résultat d’une coordination est confirmé et non présumé.',
 para('Le plan distingue une demande, une acceptation et une prestation effectivement réalisée. Le responsable du suivi sait quel résultat doit être vérifié, comment joindre le relais et à quel changement réagir. Cette organisation est ajustée au risque plutôt qu’à une date standard inventée.',
 'Si le relais n’est pas disponible, l’équipe revoit le plan. Elle ne remet pas la même consigne à la personne en la considérant responsable d’un obstacle institutionnel. La responsabilité de l’intervalle est clarifiée pour éviter une période où chaque intervenant pense que l’autre assure le suivi.',
 'Le médecin conserve la différence entre une solution administrative et un résultat de santé. Un dossier complet peut coexister avec une aggravation médicale; un symptôme amélioré peut coexister avec un logement ou un soutien encore inadapté. Les deux dimensions continuent à être suivies.')+refs('S02','S03','S09','S18'))+'</section>'

def main():
 results=[]
 for part,indices in PARTS.items():
  name=f'LOT_226_Appel_B_V8_Partie_{part}_DX.{indices[0]}_a_DX.{indices[-1]}.html'
  body=p('Le fichier développe des scénarios transversaux du SSP O7.4, sous un plan académique en quatorze points. Les cas sont fictifs et les dates des sources restent explicites. L’ordre pédagogique fixé par l’Appel A est conservé; il ne prétend pas classer des fréquences suisses comparables.')
  body+='<div class="scope">'+p('Vial a explicitement demandé de poursuivre les Appels B malgré les réserves sur les Appels A. Ce fichier reste un brouillon: aucun score de validation indépendante ni contrôle visuel à 390 px n’est présumé. Le seuil final, les réserves de l’Appel A et l’absence de validation clinique humaine restent applicables.')+'</div>'
  body+=window('Les sigles et unités gardent leur sens avant la lecture.',p('La Situation as Starting Point (SSP) désigne une situation de départ de PROFILES. L’Office fédéral de la santé publique (OFSP), l’Observatoire suisse de la santé (Obsan), l’Office fédéral de l’environnement (OFEV), le Centre hospitalier universitaire vaudois (CHUV) et l’Académie suisse des sciences médicales (ASSM) fournissent les sources citées. La plate-forme suisse d’information sur les médicaments est désignée AIPS.')+p('Le Code civil (CC), le Code des obligations (CO), le Code pénal (CP), la loi sur l’assurance-maladie (LAMal), la loi sur l’assurance-invalidité (LAI) et l’ordonnance sur la protection de l’air (OPair) sont distingués. L’assurance-invalidité est abrégée AI. Le Centre national pour les services climatiques est abrégé NCCS.')+p('La Classification internationale des maladies, onzième révision, est abrégée CIM-11. Le becquerel par mètre cube (Bq/m³) mesure une concentration d’activité radioactive; le microgramme par mètre cube (µg/m³) mesure une concentration massique. Les particules PM2,5 et PM10 désignent les fractions de diamètre aérodynamique inférieur à 2,5 et 10 micromètres; le dioxyde d’azote est noté NO2. Le litre par jour est noté L/j. Les valeurs de concentration conservent leur période de moyenne.'))
  body+='<nav aria-label="Navigation des scénarios">'+''.join(f'<a href="#dx{n}">Le scénario DX.{n} est accessible.</a>' for n in indices)+'<a href="#sources">Les sources sont accessibles.</a></nav>'
  for n in indices:body+=build_mono(n)
  body+=shared_tools(indices)+legal_appendix(part)
  body+=window('Le questionnaire garde les limites ouvertes avant validation.',p('LOT_226 · Partie'+str(part)+' · Les posologies, spécialités et adaptations de produits non lues dans AIPS restent à vérifier avant prescription. La source attendue est la fiche professionnelle suisse la plus récente, avec le numéro d’autorisation réellement lu et un extrait exact applicable à la décision.')+p('LOT_226 · Partie'+str(part)+' · Le contrôle visuel à 390 px reste à réaliser dans un environnement autorisé. Le refus de la politique du navigateur lors de l’Appel A ne doit pas être contourné. Les contrôles statiques de ce fichier ne constituent pas ce contrôle visuel.')+p('LOT_226 · Partie'+str(part)+' · Chaque scénario doit encore recevoir une relecture indépendante de fond et de conformité. Les sources non rouvertes par l’auditeur ne seront pas décrites comme vérifiées indépendamment. Une note ne sera calculée qu’après lecture effective.'))
  size=page(name,f'Appel B · La partie {part} développe  DX.{indices[0]} à DX.{indices[-1]}.',body,f'LOT_226_B_P{part}')
  b=(ROOT/name).read_bytes();results.append({'partie':part,'fichier':name,'octets':size,'sha256':hashlib.sha256(b).hexdigest(),'monographies':indices,'audit_independant':False,'rendu_390_verifie':False})
 (ROOT/'CONTROLE_PRODUCTION_B.json').write_text(json.dumps(results,ensure_ascii=False,indent=2))
 print(json.dumps(results,ensure_ascii=False))
if __name__=='__main__':main()
